    override func viewDidLoad() { super.viewDidLoad(); title = "TrueCut"; view.backgroundColor = .black; setupUI(); requestCamera() }
    override func viewDidLayoutSubviews() { super.viewDidLayoutSubviews(); preview.frame = view.bounds }
    private func setupUI() {
        preview.videoGravity = .resizeAspectFill; view.layer.insertSublayer(preview, at: 0)
        let top = UIBuilder.label("RECORD A PROTECTED ORIGINAL", style: AppTypography.caption, color: .white); top.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(top); status.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(status); timerLabel.translatesAutoresizingMaskIntoConstraints = false; view.addSubview(timerLabel)
        recordButton.translatesAutoresizingMaskIntoConstraints = false; recordButton.backgroundColor = .white; recordButton.layer.cornerRadius = 36; recordButton.layer.borderWidth = 7; recordButton.layer.borderColor = UIColor.white.withAlphaComponent(0.35).cgColor; recordButton.addTarget(self, action: #selector(toggleRecording), for: .touchUpInside); recordButton.accessibilityLabel = "Record protected video"; view.addSubview(recordButton)
