    private func requestCamera() { switch AVCaptureDevice.authorizationStatus(for: .video) { case .authorized: configureSession(); case .notDetermined: AVCaptureDevice.requestAccess(for: .video) { [weak self] granted in DispatchQueue.main.async { if granted { self?.configureSession() } else { self?.showPermission() } } }; default: showPermission() } }
    private func configureSession() { DispatchQueue.global(qos: .userInitiated).async { [weak self] in guard let self else { return }; session.beginConfiguration(); session.sessionPreset = .high; defer { session.commitConfiguration(); session.startRunning(); DispatchQueue.main.async { self.preview.session = self.session } }; guard let camera = AVCaptureDevice.default(for: .video), let input = try? AVCaptureDeviceInput(device: camera), session.canAddInput(input), session.canAddOutput(movieOutput) else { return }; session.addInput(input); session.addOutput(movieOutput); if let connection = movieOutput.connection(with: .video), connection.isVideoOrientationSupported { connection.videoOrientation = .portrait } } }
