    @objc private func focus(_ gesture: UITapGestureRecognizer) { let point = gesture.location(in: view); guard let device = (session.inputs.first as? AVCaptureDeviceInput)?.device, device.isFocusPointOfInterestSupported else { return }; let focus = preview.captureDevicePointConverted(fromLayerPoint: point); try? device.lockForConfiguration(); device.focusPointOfInterest = focus; device.focusMode = .autoFocus; device.unlockForConfiguration() }
